settings.cellContentFunction:
var color;
var active = value;
if (active == 1) { // all key values here are strings
  color = '#27AE60';
} else {
  color = '#EB5757';
}
return '<span style="font-size: 18px; color: ' + color + '">&#11044;</span>';

var color;
var bgColor;
var textValue;
if (value == 'error') { // all key values here are strings
  color = 'rgba(209, 40, 40, 1)'
  bgColor = 'rgba(255, 235, 238, 1)'
  textValue = 'Error'
;
} else if (value == 'downloading') {
  color = 'rgba(54, 101, 192, 1)';
  bgColor = 'rgba(227, 242, 253, 1)';
  textValue = 'Downloading'
}
else if (value == "installing"){
    color = 'rgba(54, 101, 192, 1)';
  bgColor = 'rgba(227, 242, 253, 1)';
  textValue = 'Installing'
}
else{
    color = 'rgba(46, 125, 62, 1)'
    bgColor = 'rgba(232, 245, 233, 1)'
    textValue = 'Up to date'
}
return '<span style="color: ' + color + '; background-color: ' + bgColor + '; padding: 4px 8px; border: 1px solid ' + color + '; border-radius: 12px;">' + textValue + '</span>';

